1	import { NextResponse } from "next/server";
2	import { db } from "@/db";
3	import { failureResponse, sessionUser, unauthorized } from "@/lib/online/http";
4	import { getSaveBlob, putSaveBlob } from "@/lib/online/worldsService";
5	
6	type Params = { params: Promise<{ id: string }> };
7	
8	/**
9	 * GET /api/worlds/:id/save — the gzipped SaveData blob. The concurrency stamp
10	 * and save version ride response headers so the body stays raw bytes.
11	 */
12	export async function GET(request: Request, { params }: Params) {
13	  const user = await sessionUser(request);
14	  if (!user) return unauthorized();
15	  const { id } = await params;
16	  const result = await getSaveBlob(db(), user.id, id);
17	  if (!result.ok) return failureResponse(result.error);
18	  if (!result.blob) return NextResponse.json({ error: "no-save" }, { status: 404 });
19	  return new NextResponse(Buffer.from(result.blob), {
