    const bomb = Bun.gzipSync(new Uint8Array(8 * 1024 * 1024));
    expect(bomb.byteLength).toBeLessThan(64 * 1024); // a tiny blob, by construction

    expect(await parseSaveBlob(bomb, 1024 * 1024)).toBeNull();
  });

