    // Padded well past the bomb test's cap, to pin that the null above is the
    // cap firing rather than anything about large-but-legitimate saves.
    const padded = { ...minimalSave(), pad: "x".repeat(2 * 1024 * 1024) };
    expect(await parseSaveBlob(gzip(JSON.stringify(padded)))).not.toBeNull();
  });

