    expect(MAX_DECOMPRESSED_SAVE_BYTES).toBeGreaterThan(16 * 1024 * 1024);
    expect(MAX_DECOMPRESSED_SAVE_BYTES).toBeLessThan(256 * 1024 * 1024);
