/**
 * Drains the pending snapshot, one push at a time. Latest-wins: a snapshot
 * queued while a push is in flight replaces any earlier one, because they
 * describe the same world and only the newest is worth sending. Not tied to
 * the React lifecycle (refs outlive it), so an in-flight push still survives
 * an unmount the way the old fire-and-forget did.
 */
const drainCloudPushes = useCallback(
  async (cloudId: string) => {
    if (pushInFlightRef.current) return;
    pushInFlightRef.current = true;
    try {
      while (pushPendingRef.current && !cloudConflictRef.current) {
        const { save, notify } = pushPendingRef.current;
        pushPendingRef.current = null;
        if ((await pushSave(cloudId, save)) === "conflict") {
          cloudConflictRef.current = true;
          if (notify) flashMessage("This world changed on another device — your changes here won't sync. Reopen to catch up.");
        }
      }
    } finally {
      pushInFlightRef.current = false;
    }
  },
  [flashMessage]
);

// Mirror a cloud-linked SP save up after a local write. `notify` toasts once
// on a losing write, so the player knows another device took over — we then
// stop pushing to avoid a last-writer-wins clobber; the next open pulls their
// save.
const syncCloudSave = useCallback(
  (engine: GameApi, notify: boolean) => {
    const cloudId = cloudIdRef.current;
    if (!cloudId || onlineRef.current || cloudConflictRef.current) return;
    // Serialize synchronously: the engine keeps mutating, and the unload
    // flush needs the state as of ITS call, not whenever the push starts.
    // `notify` sticks if any coalesced snapshot wanted it — dropping a
    // snapshot must not drop the warning that it lost.
    pushPendingRef.current = { save: engine.serialize(), notify: notify || (pushPendingRef.current?.notify ?? false) };
    void drainCloudPushes(cloudId);
  },
  [drainCloudPushes]
);

