40	/**
41	 * The client end of a multiplayer world: owns the WebSocket and a REPLICA
42	 * engine the existing renderer/audio/HUD consume unchanged. Outbound, it
43	 * streams the local player's pose at tick rate and routes commands — local
44	 * presentation stays on the replica, gameplay goes to the server (selectSlot
45	 * optimistically does both). Inbound, it applies the server's block journal,
46	 * replays events into the shell's existing event drain, feeds pose buffers
47	 * for ~125 ms-delayed interpolation, and overwrites the local player's
48	 * private state from self-deltas (the server owns your vitals).
49	 *
50	 * The engine outlives the socket: a dropped connection (anything but a fatal
51	 * close — a bad ticket, a kick, a slow-client shed) runs a reconnect ladder
52	 * that mints a fresh ticket and redoes the handshake, re-syncing the same
53	 * replica in place — the player sees a brief "reconnecting" badge, not a
54	 * dead world.
55	 */
56	
57	export type NetStatus = "connecting" | "syncing" | "online" | "reconnecting" | "closed";
58	
59	/** A fresh place to connect: the reconnect ladder calls this to re-mint a ticket. */
60	export type JoinGrant = { url: string; ticket: string };
61	
62	export type NetworkSessionCallbacks = {
63	  onStatus?(status: NetStatus, detail?: string): void;
64	  onChat?(entry: { from: string; name: string; text: string }): void;
65	  /** Server events the shell's drain should also see (toasts, audio, particles). */
66	  onEvent?(event: GameEvent): void;
67	  /**
68	   * The LOCAL player's dimension changed (server-initiated travel): the
69	   * replica engine was just rebuilt for it, so the shell must rebuild the
70	   * renderer (dimension profiles are construction-time) — the ws stays open.
71	   */
72	  onDimension?(dimension: DimensionId): void;
73	};
74	
75	export type NetworkSessionOptions = {
76	  /** Socket factory (tests inject a fake). */
77	  makeSocket?: (url: string) => WebSocket;
78	  /** Re-mint a ticket for the reconnect ladder; omit to disable reconnection. */
79	  reconnect?: () => Promise<JoinGrant | null>;
80	  /** Artificial round-trip delay (ms) for local latency testing; overridable at runtime. */
81	  simulatedLatencyMs?: number;
82	  /** Replica world footprint — tests shrink it; production must match the server's (default). */
83	  worldSize?: { x: number; y: number; z: number };
84	};
85	
86	/** Closes we don't retry: the door said no, or we'd just be kicked again. */
87	const FATAL_CLOSES = new Set<number>([CLOSE_BAD_TICKET, CLOSE_PROTOCOL_MISMATCH, CLOSE_ROOM_FULL, CLOSE_KICKED, CLOSE_SLOW_CLIENT]);
88	
89	/** Commands that never leave the client: pure presentation on the replica. */
90	const LOCAL_COMMANDS = new Set<Command["type"]>(["toggleInventory", "toggleAdvancements", "toggleDebug", "toggleCameraView", "pause", "resume"]);
91	
92	const HANDSHAKE_TIMEOUT_MS = 15000;
93	
94	/** Ping cadence — 1 Hz keeps the clock's min-RTT window (~16 samples) fresh at ~40 B/s. */
95	const PING_INTERVAL_MS = 1000;
96	
97	/** One player as the roster panel shows them (dimension drives the "· Nether" tag). */
98	export type RosterMember = { id: PlayerId; name: string; dimension: DimensionId };
99	
100	/** Live connection stats for the F3 overlay (poll, don't subscribe). */
101	export type NetStats = {
102	  rttMs: number;
103	  /** Tick inter-arrival jitter (p90 deviation from the 50 ms nominal). */
104	  jitterMs: number;
105	  /** How far in the past remote entities currently render. */
106	  interpDelayMs: number;
107	  inKBps: number;
108	  outKBps: number;
109	  /** Optimistic block edits awaiting server confirmation. */
110	  pendingPredictions: number;
111	};
112	
113	export type NetworkSession = {
114	  /** The live replica engine. REBOUND on dimension travel — re-read it after onDimension, never cache it across a swap. */
115	  readonly engine: GameEngine;
116	  readonly playerId: PlayerId;
