118	  readonly role: "owner" | "member";
119	  /** UI subscriptions (React components mount after connect; unsubscribe on cleanup). */
120	  subscribeChat(listener: (entry: { from: string; name: string; text: string }) => void): () => void;
121	  subscribeStatus(listener: (status: NetStatus) => void): () => void;
122	  /** Fires whenever a player joins or leaves — the roster panel re-reads roster(). */
123	  subscribeRoster(listener: () => void): () => void;
124	  status(): NetStatus;
