// ── inbound frame processing (latency-shifted) ──────────────────────────────
//
// Frames must APPLY in arrival order, not just start in it. processServerFrame
// is async — the binary worldSync awaits gunzip, which in a browser spans
// several macrotasks — so firing frames concurrently let a later `tick` finish
// and apply its blocks while an older worldSync was still inflating, then the
// worldSync landed on top and clobbered them. (Bun's synchronous gunzip masks
// this, so it never showed in tests.) A one-frame-at-a-time queue chains each
// frame's promise after the last, so completion order matches arrival — the
// FIFO the delayLine above already assumes downstream. Errors are swallowed so
// one bad frame can't wedge the chain.
let inboundTail: Promise<void> = Promise.resolve();
const enqueueFrame = (data: unknown) => {
  inboundTail = inboundTail.then(() => processServerFrame(data)).catch(() => {});
};
const onServerFrame = (data: unknown) => {
  traffic.inBytes += typeof data === "string" ? data.length : ((data as ArrayBuffer).byteLength ?? 0);
  if (simulatedLatencyMs > 0 || simulatedJitterMs > 0) {
    recvLine.push(() => enqueueFrame(data));
    return;
  }
  enqueueFrame(data);
};

