import { expect, test } from "bun:test";
import { PGlite } from "@electric-sql/pglite";
import { readFileSync, readdirSync } from "node:fs";

async function apply(pg: PGlite, file: string) {
  for (const s of readFileSync(`db/migrations/${file}`, "utf8").split("--> statement-breakpoint")) if (s.trim()) await pg.exec(s);
}

test("0005 trigger: blob change bumps, rename doesn't, first upload 0->1", async () => {
  const pg = new PGlite();
  for (const f of readdirSync("db/migrations").filter((f) => f.endsWith(".sql")).sort()) await apply(pg, f);
  await pg.exec(`INSERT INTO "user"(id,name,email) VALUES('u','u','u@e.com');`);
  await pg.exec(`INSERT INTO worlds(id,owner_id,kind,name,seed,worldgen_version) VALUES('w','u','sp-cloud','W',1,12);`);

  const rev = async () => (await pg.query<{ save_revision: number }>(`SELECT save_revision FROM worlds WHERE id='w'`)).rows[0].save_revision;
  expect(await rev()).toBe(0);

  // First upload (NULL -> blob), OLD-style: sets only save_blob, no save_revision.
  await pg.exec(`UPDATE worlds SET save_blob='\\x01'::bytea, updated_at=now() WHERE id='w';`);
  expect(await rev()).toBe(1); // trigger bumped 0->1

  await pg.exec(`UPDATE worlds SET save_blob='\\x02'::bytea WHERE id='w';`);
  expect(await rev()).toBe(2); // changed blob bumps

  await pg.exec(`UPDATE worlds SET name='Renamed', updated_at=now() WHERE id='w';`);
  expect(await rev()).toBe(2); // rename doesn't touch save_blob -> no bump

  await pg.exec(`UPDATE worlds SET save_blob='\\x02'::bytea WHERE id='w';`);
  expect(await rev()).toBe(2); // identical blob -> no bump

  await pg.close();
});
EOF
