7	 * Room persistence: where a world's row and gzipped v17 save blob live.
8	 * Postgres (the same tables the web API writes) in production; the in-memory
9	 * adapter backs tests and PERSISTENCE=memory mode (DB-less local iteration
10	 * and the Playwright multiplayer spec — unknown world ids are auto-created
11	 * with a seed derived from the id).
12	 */
13	
14	export type WorldRecord = {
15	  id: string;
16	  seed: number;
17	  worldType: string;
18	  difficulty: string;
19	  hardcore: boolean;
20	  save: SaveData | null;
21	};
