28	/**
29	 * Hard ceiling on a decompressed save. Gzip ratios run ~1000:1 on hostile
30	 * input, so an unbounded inflate turns a few MiB of stored bytes into GiB of
31	 * heap on a 512 MB VM. Generous next to any real world (a save is a block diff,
32	 * not a voxel dump) but bounded, so a malformed or crafted row fails this room
33	 * rather than the process.
34	 */
35	export const MAX_DECOMPRESSED_SAVE_BYTES = 96 * 1024 * 1024;
36	
37	/**
38	 * Inflates gzip with a running output cap, cancelling the stream the moment it
39	 * exceeds `maxBytes` — so the cap bounds what is ALLOCATED, not merely what is
40	 * returned (which is what checking `.byteLength` after a `gunzipSync` would do).
41	 */
42	async function gunzipBounded(blob: Uint8Array, maxBytes: number): Promise<string | null> {
43	  const reader = new Blob([blob as BlobPart]).stream().pipeThrough(new DecompressionStream("gzip")).getReader();
44	  const chunks: Uint8Array[] = [];
45	  let total = 0;
46	  try {
47	    for (;;) {
48	      const { done, value } = await reader.read();
49	      if (done) break;
50	      total += value.byteLength;
51	      if (total > maxBytes) {
52	        await reader.cancel();
53	        return null;
54	      }
55	      chunks.push(value);
56	    }
57	  } catch {
58	    return null;
59	  }
60	  const merged = new Uint8Array(total);
61	  let offset = 0;
62	  for (const chunk of chunks) {
63	    merged.set(chunk, offset);
64	    offset += chunk.byteLength;
65	  }
66	  return new TextDecoder().decode(merged);
67	}
68	
69	/**
70	 * Parses a stored gzipped SaveData blob through the full readSave
71	 * validation/migration chain, bounded by MAX_DECOMPRESSED_SAVE_BYTES.
72	 *
73	 * Since save PUT is `sp-cloud`-only (lib/online/worldsService.ts) a room should
74	 * only ever read blobs the server itself wrote, so the bound is depth rather
75	 * than a live vector — but this is the seam where stored bytes become engine
76	 * state, and it should not trust the row on the far side of it.
77	 */
78	export async function parseSaveBlob(blob: Uint8Array, maxBytes = MAX_DECOMPRESSED_SAVE_BYTES): Promise<SaveData | null> {
79	  try {
80	    // readSave via a one-key Storage shim, so the entire migration + validation
81	    // pipeline applies to server-loaded saves too.
82	    const json = await gunzipBounded(blob, maxBytes);
83	    if (json === null) return null;
84	    const shim = { getItem: () => json } as unknown as Storage;
85	    return readSave("blob", shim);
86	  } catch {
87	    return null;
88	  }
89	}
