107	      // save_blob changes — the room is just another writer, and a browser
108	      // reading this world's blob compares that number. Not set here, so a
109	      // deploy where the trigger is present but this build isn't still counts.
110	      await database.update(schema.worlds).set({ saveBlob: blob, saveVersion, updatedAt: new Date() }).where(eq(schema.worlds.id, worldId));
111	    }
112	  };
113	}
