117	  let hash = 0x811c9dc5;
118	  for (let i = 0; i < id.length; i += 1) {
119	    hash ^= id.charCodeAt(i);
120	    hash = Math.imul(hash, 0x01000193);
121	  }
122	  return (hash >>> 0) % 2147483647;
