74	  /**
75	   * Evicts rooms that have sat empty. The room leaves `rooms` and enters
76	   * `evicting` in the same synchronous step: a join must never reach a room
77	   * that is closing its sockets, but must also not load a second copy of the
78	   * world from the blob this shutdown is still writing. Between those two
79	   * states there is no window — dropping it from `rooms` and only THEN awaiting
80	   * shutdown is what let a join build a rival room from pre-shutdown state,
81	   * with two Rooms then writing one row under an UPDATE that has no version
82	   * guard (last write wins, and the eviction's is usually the older).
83	   */
84	  async sweepIdle(): Promise<void> {
85	    for (const [worldId, room] of this.rooms) {
86	      if (room.playerCount() === 0 && room.emptySinceMs !== null && this.now() - room.emptySinceMs > IDLE_EVICT_MS) {
87	        this.rooms.delete(worldId);
88	        const done = room.shutdown();
